/**
 * MonMag localization.
 *
 * Ten world-recognized languages are supported. Each translation row is
 * ordered to match LOCALES, so adding a language requires one new column.
 * Missing entries fall back to English instead of throwing at render time.
 */
export const LOCALES = [
  "en",
  "es",
  "fr",
  "de",
  "zh",
  "ja",
  "ar",
  "pt",
  "hi",
  "id",
] as const;

export type Locale = (typeof LOCALES)[number];

const LOCALE_TAGS: Record<Locale, string> = {
  en: "en-US",
  es: "es-ES",
  fr: "fr-FR",
  de: "de-DE",
  zh: "zh-CN",
  ja: "ja-JP",
  ar: "ar-SA",
  pt: "pt-BR",
  hi: "hi-IN",
  id: "id-ID",
};

/** Numeric dates use day/month/year consistently, including for English. */
const DATE_LOCALE_TAGS: Record<Locale, string> = {
  ...LOCALE_TAGS,
  en: "en-GB",
};

export function isLocale(value: string | null | undefined): value is Locale {
  return !!value && (LOCALES as readonly string[]).includes(value);
}

/** Resolve a stored preference (which may be a regional tag) to a supported locale. */
export function localeOf(
  language: string | null | undefined,
  fallback: Locale = "en",
): Locale {
  if (isLocale(language)) return language;
  const base = language?.toLowerCase().split(/[-_]/)[0];
  return isLocale(base) ? base : fallback;
}

export function localeTag(locale: Locale): string {
  return LOCALE_TAGS[locale] ?? LOCALE_TAGS.en;
}

export function dateLocaleTag(locale: Locale): string {
  return DATE_LOCALE_TAGS[locale] ?? DATE_LOCALE_TAGS.en;
}

export function textDirection(locale: Locale): "ltr" | "rtl" {
  return locale === "ar" ? "rtl" : "ltr";
}

/** Endonyms keep the language picker recognizable in every locale. */
export const LOCALE_NAMES: Record<Locale, string> = {
  en: "English",
  es: "Español",
  fr: "Français",
  de: "Deutsch",
  zh: "中文",
  ja: "日本語",
  ar: "العربية",
  pt: "Português",
  hi: "हिन्दी",
  id: "Bahasa Indonesia",
};

