export type TranslationKey = keyof typeof translations;

export function isTranslationKey(value: unknown): value is TranslationKey {
  return typeof value === "string" && Object.prototype.hasOwnProperty.call(translations, value);
}

export function t(
  locale: Locale | string | undefined,
  key: TranslationKey,
  params: Record<string, string | number> = {},
): string {
  const active = localeOf(locale);
  const index = LOCALES.indexOf(active);
  const values = translations[key];
  const template = values?.[index] ?? values?.[0] ?? key;
  return template.replace(/\{(\w+)\}/g, (_, name: string) =>
    String(params[name] ?? `{${name}}`),
  );
}
